import re

if '$change_me.title' == 'syslog: User authentication failure.':
    log_line = '$change_me.all_fields.full_log'

    # Expression régulière pour capturer le nom d'utilisateur après "user="
    match = re.search(r'user=([^\s]+)', log_line)

    if match:
        username = match.group(1)
        print(username)
    else:
        print("Nom d'utilisateur non trouvé.")
else:
    print('$change_me.all_fields.data.win.eventdata.targetUserName')
